-- 009 飯田市オープンデータ「指定緊急避難場所一覧」の避難場所を、市の CSV にそろえる。
-- このファイルは npm run evacuation:sql で作る。手で編集しない（手順は docs/009_ingest-city-opendata.md）
-- CSV：https://www.city.iida.lg.jp/uploaded/attachment/78765.csv

update public.data_sources set
  credit_text = '出典：飯田市（https://www.city.iida.lg.jp/soshiki/168/opendata.html）、PDL1.0（https://www.digital.go.jp/resources/open_data/public_data_license_v1.0）（2026年10月26日に利用）。「指定緊急避難場所一覧」（飯田市）（https://www.city.iida.lg.jp/soshiki/168/opendata.html）を加工して作成（同じ場所の行をまとめ、緯度経度のない一部の場所に位置を補った）',
  period_label = '2025年12月19日更新',
  checked_on = '2026-10-26'::date
where id = 'iida_evacuation';

delete from public.facilities where source_id = 'iida_evacuation';
